export default async function ResearchPage({
  params
}: {
  params: Promise<{
    id: string;
  }>;
}) {
  const {
    id
  } = await params;
  let owner: string;
  try {
    owner = await requireOwner();
  } catch {
    redirect(`/sign-in?redirect_url=${encodeURIComponent(`/research/${id}`)}`);
  }
  const run = await ownedRun(id, owner);
  if (!run) notFound();
  if(run.mode === "autonomous") return <AgentConversation initial={run} ownerId={owner} signedIn authConfigured/>;
  if (run.report) redirect(`/reports/${id}`);
  return <RunProgress initial={run} />;
}
import type { IdeaBrief, RunStage, RunState } from "./types";

// Home needs summaries, never the report body or provider operation journal.
export type HomeRun = {
  id: string;
  idea: string;
  category: IdeaBrief["category"];
  status: RunState["status"];
  stage: RunStage;
  createdAt: string;
  parentId: string | null;
  title: string | null;
  hasReport: boolean;
  mode?: "legacy" | "autonomous";
  recovery?: "working" | "recovering" | "reconciling";
};

export type HomeNext =
  | { kind: "active" | "report" | "paused"; run: HomeRun }
  | { kind: "draft"; draft: IdeaBrief }
  | { kind: "empty" };

export function homeNext(runs: HomeRun[], draft: IdeaBrief | null): HomeNext {
  const newest = [...runs].sort((a, b) =>
    b.createdAt.localeCompare(a.createdAt)
  );
  const active = newest.find(
    (run) =>
      !run.hasReport && (run.status === "queued" || run.status === "running")
  );
  if (active) return { kind: "active", run: active };
  // Older submissions left a device draft behind. Prefer its saved report
  // without deleting local input or hiding a draft for an unrelated idea.
  const normalizeIdea = (idea: string) =>
    idea.trim().replace(/\s+/g, " ").toLowerCase();
  const submittedDraft =
    draft &&
    newest.find(
      (run) =>
        run.hasReport &&
        run.category === draft.category &&
        normalizeIdea(run.idea) === normalizeIdea(draft.idea)
    );
  if (submittedDraft) return { kind: "report", run: submittedDraft };
  if (draft) return { kind: "draft", draft };
  const report = newest.find((run) => run.hasReport);
  if (report) return { kind: "report", run: report };
  const paused = newest.find((run) => run.status === "failed");
  return paused ? { kind: "paused", run: paused } : { kind: "empty" };
}

export const homeCategories = {
  software: "Software",
  physical: "Physical product",
  service: "Service",
};
export const homeStages: Record<RunStage, string> = {
  queued: "Waiting for a research slot",
  discovering: "Looking for what exists",
  verifying: "Checking the closest matches",
  composing: "Finding a useful next step",
  finances: "Checking the financial model",
  complete: "Report ready",
};

export function homeRunHref(run: HomeRun) {
  return `/${
    run.mode === "autonomous"
      ? "research"
      : run.hasReport
      ? "reports"
      : "research"
  }/${run.id}`;
}
