  try {
    sessionStorage.setItem(FRESH_KEY, JSON.stringify(draft));
    return true;
  } catch {
    return false;
  }
}
export function clearFreshDraft() {
  try {
    sessionStorage.removeItem(FRESH_KEY);
  } catch {}
}
